package com.dpworld.fms.routing;
import static org.junit.jupiter.api.Assertions.*;import com.dpworld.fms.domain.*;import java.util.*;import org.junit.jupiter.api.Test;
class ProductionRoutingServiceTest{@Test void persistsOptimalRouteAndGeoJson(){var a=new MapNode("A",new GeoPoint(25,55));var b=new MapNode("B",new GeoPoint(25,55.001));var c=new MapNode("C",new GeoPoint(25,55.002));var slow=edge("slow","A","C",100,10);var ab=edge("ab","A","B",100,50);var bc=edge("bc","B","C",100,50);UUID graph=UUID.randomUUID();var graphs=new RoutingGraphRepository(){public Optional<RoutingGraph>findActiveApproved(){return Optional.of(new RoutingGraph(graph,4,"ACTIVE",List.of(a,b,c),List.of(slow,ab,bc)));}public Optional<RoutingGraph>findById(UUID id){return findActiveApproved();}};List<PlannedRouteRepository.PlannedRoute>saved=new ArrayList<>();var routes=new PlannedRouteRepository(){public UUID save(PlannedRoute r){saved.add(r);return r.id();}public Optional<PlannedRoute>find(UUID id){return saved.stream().filter(x->x.id().equals(id)).findFirst();}};var result=new ProductionRoutingService(graphs,routes).calculate(new RouteRequest("A","C",AssetType.ITV,new VehicleEnvelope(3,2,6,20),10000,50),null);assertTrue(result.valid());assertEquals(List.of("ab","bc"),result.route().segments().stream().map(RoadSegment::id).toList());assertTrue(result.geoJson().contains("LineString"));assertEquals(4,saved.getFirst().graphVersion());}@Test void returnsInvalidWithoutApprovedGraph(){var graphs=new RoutingGraphRepository(){public Optional<RoutingGraph>findActiveApproved(){return Optional.empty();}public Optional<RoutingGraph>findById(UUID id){return Optional.empty();}};var routes=new PlannedRouteRepository(){public UUID save(PlannedRoute r){fail();return null;}public Optional<PlannedRoute>find(UUID id){return Optional.empty();}};assertEquals("NO_ACTIVE_APPROVED_GRAPH",new ProductionRoutingService(graphs,routes).calculate(new RouteRequest("A","B",AssetType.ITV,new VehicleEnvelope(3,2,6,20),1,1),null).failureReason());}private RoadSegment edge(String id,String from,String to,double distance,double speed){return new RoadSegment(id,from,to,distance,speed,1,1,false,false,Set.of(),0,0,0);}}
